from ._tulis import Q, bab, kursus, latihan

def P(ch, lv, stem, ok_text, wrong, why, pos):
    """Soal dengan kunci di posisi pos (0-3). wrong = tiga pengecoh."""
    opts = list(wrong)
    opts.insert(pos, ok_text)
    return Q(ch, lv, stem, *opts, "abcd"[pos], why)

